    for cell in diff:
        r0,r1,c0,c1=cell[0],cell[1]
        # flood fill connected non-bg region from cell
        stack=[(r0,c0)]; 
        cells=[]; 
        while stack:
            rr,cc=stack.pop(); cells.append((rr,cc))
            if (rr,cc) in seen or g[rr][cc]==bg: continue
            seen.add((rr,cc))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=(rr+dr,cc+dc)
                    if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]!=bg and n not in seen:
                        stack.append(n)
        # direction of extension: down-right diagonal
        for dr,dc in ((1,1)):
            for rr,cc in cells:
                r,c=rr,cc
                while True:
                    nr,nc=r+dr,c+dc
                    if nr>=H or nc>=W: break
                    if g[nr][nc]==bg:
                        out[nr][nc]=g[rr][cc]
                        r,c=nr,nc
                    else:
                        break
    return out
