    for root,dirs,files in os.walk(d):
        if 'sessions' in str(root) or 'system/state/sessions' in str(root):
            continue
        for fn in files:
            fp=os.path.join(root,fn)
            if not fn.endswith('.jsonl'): continue
            try: t=open(fp).read().replace('\\n','\n')
            except Exception: continue
            for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\)',t):
                k,h,w=m[1],int(m[2]),int(m[3])
                rows=[r.split() for r in t[m.end():].split('\n')[:h]]
                if all(len(x)==w and all(y.isdigit() for y in x) for x in rows) and k not in G:
                    G[k]=[[int(yy) for yy in x] for x in rows]
    return G
G=load(); print(sorted(G))
print(json.dumps(G.get('Test input')))
